from itertools import combinations
import heapq


def _jobs_solver(capacity, tie):
    def solve(data):
        jobs = data["jobs"]
        k = data["k"]
        blocked = set(data.get("blocked", []))
        mandatory = set(data.get("mandatory", []))
        options = [job for job in jobs if job["id"] not in blocked]
        best_ids = None
        best_value = None

        for picked in combinations(options, k):
            ids = sorted(job["id"] for job in picked)
            if not mandatory.issubset(ids):
                continue
            counts = Counter(job["group"] for job in picked)
            if any(not low <= counts[group] <= high
                   for group, (low, high) in data.get("quotas", {}).items()):
                continue
            active = []
            valid = True
            for job in sorted(picked, key=lambda j: (j["start"], j["end"])):
                active = [end for end in active if end > job["start"]]
                active.append(job["end"])
                if len(active) > capacity:
                    valid = False
                    break
            if not valid:
                continue
            value = sum(job["value"] for job in picked)
            if (best_ids is None or value > best_value or
                    (value == best_value and
                     (ids < best_ids if tie == "smallest" else ids > best_ids))):
                best_ids, best_value = ids, value

        if best_ids is None:
            return {"error": "impossible"}
        return {"selected": best_ids, "value": best_value}
    return solve


def _build_component_06():
    def round_ratio(numerator, denominator, mode):
        if mode == "half_up":
            return (numerator + denominator // 2) // denominator
        return numerator // denominator

    def solve(data):
        cutoff = data.get("cutoff", 10**9)
        winners = {}
        for pos, event in enumerate(data["events"]):
            sequence = event.get("sequence", 0)
            if sequence > cutoff:
                continue
            event_id = event.get("id", "anonymous:" + str(pos))
            key = (sequence, event.get("revision", 0), pos)
            if event_id not in winners or key > winners[event_id][0]:
                winners[event_id] = (key, event)

        balances = dict(data.get("opening", {}))
        mode = data["rounding"]
        for _, event in winners.values():
            if event.get("void", False):
                continue
            raw = event["price"] * event.get("quantity", 1)
            discount = min(10000, max(0, event.get("discount_bp", 0)))
            net = round_ratio(raw * (10000 - discount), 10000, mode)
            tax = round_ratio(net * event.get("tax_bp", 0), 10000, mode)
            amount = net + tax
            if event.get("kind") == "refund":
                amount = -amount
            key = event.get("account", "default") + "|" + event.get("currency", "USD")
            balances[key] = balances.get(key, 0) + amount
        return {"balances": balances}
    return solve


def _build_component_07():
    def solve(data):
        packages = data["packages"]
        names = sorted(packages)
        features = set(data.get("features", []))
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        initial = {name: [tuple(bounds)] for name, bounds in data["roots"].items()}
        best_vector = None
        best_versions = None

        def acyclic(edges):
            visiting, finished = set(), set()

            def visit(name):
                if name in visiting:
                    return False
                if name in finished:
                    return True
                visiting.add(name)
                for other in edges.get(name, ()):
                    if not visit(other):
                        return False
                visiting.remove(name)
                finished.add(name)
                return True

            return all(visit(name) for name in edges)

        def search(assigned, constraints, edges):
            nonlocal best_vector, best_versions
            todo = sorted(name for name in constraints if name not in assigned)
            if not todo:
                if not acyclic(edges):
                    return
                vector = tuple(assigned.get(name, -1) for name in names)
                if best_vector is None or vector > best_vector:
                    best_vector = vector
                    best_versions = dict(assigned)
                return

            name = todo[0]
            ranges = constraints[name]
            rows = [row for row in packages.get(name, [])
                    if all(low <= row["version"] <= high for low, high in ranges)
                    and row["version"] not in blocked.get(name, [])
                    and (name not in pins or row["version"] == pins[name])]
            for row in sorted(rows, key=lambda r: r["version"], reverse=True):
                version = row["version"]
                new_assigned = dict(assigned)
                new_assigned[name] = version
                new_constraints = {n: list(rs) for n, rs in constraints.items()}
                new_edges = {n: list(es) for n, es in edges.items()}
                deps = [dep for dep in row.get("deps", [])
                        if not dep.get("feature") or dep["feature"] in features]
                new_edges[name] = []
                possible = True
                for dep in deps:
                    other = dep["name"]
                    new_edges[name].append(other)
                    new_constraints.setdefault(other, []).append((dep["min"], dep["max"]))
                    if (other in new_assigned and
                            not all(lo <= new_assigned[other] <= hi
                                    for lo, hi in new_constraints[other])):
                        possible = False
                        break
                if possible:
                    search(new_assigned, new_constraints, new_edges)

        search({}, initial, {})
        if best_versions is None:
            return {"error": "unsatisfiable"}
        return {"versions": best_versions}
    return solve


def _build_component_08():
    def solve(data):
        required = data.get("required", [])
        bits = {node: 1 << i for i, node in enumerate(required)}
        full = (1 << len(required)) - 1
        initial_mask = bits.get(data["source"], 0)
        start_state = (data["source"], initial_mask, data["coupons"])
        distances = {start_state: data["start"]}
        queue = [(data["start"],) + start_state]
        graph = [[] for _ in range(data["n"])]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)

        while queue:
            time, node, mask, remaining = heapq.heappop(queue)
            state = (node, mask, remaining)
            if distances.get(state) != time:
                continue
            if node == data["target"] and mask == full and remaining == 0:
                return {"arrival": time}
            for edge in graph[node]:
                depart = max(time, edge["open"])
                if depart >= edge["close"]:
                    continue
                durations = [(edge["duration"], remaining)]
                if remaining:
                    discounted = max(2, edge["duration"] - edge.get("discount", 0))
                    durations.append((discounted, remaining - 1))
                next_node = edge["v"]
                next_mask = mask | bits.get(next_node, 0)
                for duration, next_remaining in durations:
                    arrival = depart + duration
                    if arrival > data["deadline"]:
                        continue
                    next_state = (next_node, next_mask, next_remaining)
                    if arrival < distances.get(next_state, float("inf")):
                        distances[next_state] = arrival
                        heapq.heappush(queue, (arrival,) + next_state)
        return {"arrival": None}
    return solve


